//
//  SigningE2ETests.swift
//  BatSignTests
//
//  End-to-end signing on the iOS simulator: builds a real IPA fixture and
//  runs the full production pipeline — Swift bridge -> zsign -> OpenSSL —
//  with a real p12 + provisioning profile, then verifies the signed output.
//  This is the regression net for the on-device "crash on Sign" class.
//

import XCTest
@testable import BatSign

final class SigningE2ETests: XCTestCase {
    private let p12Password = "batsign123"

    private func writeFixture(_ base64: String, name: String) throws -> URL {
        let data = try XCTUnwrap(Data(base64Encoded: base64), name)
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(name)
        try data.write(to: url, options: [.atomic])
        return url
    }

    private func makeFixtureIPA() throws -> (input: URL, output: URL) {
        let infoPlist = """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0"><dict>
        <key>CFBundleIdentifier</key><string>com.original.batfix</string>
        <key>CFBundleName</key><string>BatFixture</string>
        <key>CFBundleDisplayName</key><string>Original Name</string>
        <key>CFBundleShortVersionString</key><string>1.0</string>
        <key>CFBundleVersion</key><string>1</string>
        <key>CFBundleExecutable</key><string>BatFixture</string>
        <key>CFBundlePackageType</key><string>APPL</string>
        <key>MinimumOSVersion</key><string>15.0</string>
        </dict></plist>
        """
        let macho = try XCTUnwrap(Data(base64Encoded: Self.MACHO_BASE64), "Mach-O fixture")
        let ipa = TestArchives.zip(entries: [
            ("Payload/BatFixture.app/Info.plist", Data(infoPlist.utf8)),
            ("Payload/BatFixture.app/BatFixture", macho),
        ])
        let inputURL = FileManager.default.temporaryDirectory.appendingPathComponent("e2e-\(UUID().uuidString).ipa")
        let outputURL = FileManager.default.temporaryDirectory.appendingPathComponent("e2e-\(UUID().uuidString)-signed.ipa")
        try ipa.write(to: inputURL, options: [.atomic])
        return (inputURL, outputURL)
    }

    private func makeCert() -> CertificateRecord {
        CertificateRecord(
            id: UUID(),
            displayName: "Fixture Identity",
            commonName: "BatTest Dev",
            organization: "BatTest Org",
            kind: .development,
            teamName: "BatTest Team",
            teamID: "BATTEAM01",
            certNotBefore: nil,
            certNotAfter: nil,
            profileName: "BatTest Profile",
            profileExpiration: Calendar.current.date(byAdding: .year, value: 1, to: Date()),
            profileCreated: Date(),
            deviceCount: 1,
            bundleIDPattern: "com.bat.testapp",
            addedAt: Date()
        )
    }

    func testFullSigningPipelineWithRealIdentity() throws {
        let paths = try makeFixtureIPA()
        defer {
            try? FileManager.default.removeItem(at: paths.input)
            try? FileManager.default.removeItem(at: paths.output)
        }
        let p12URL = try writeFixture(Self.P12_BASE64, name: "fixture.p12")
        let profileURL = try writeFixture(Self.PROV_BASE64, name: "fixture.mobileprovision")
        defer {
            try? FileManager.default.removeItem(at: p12URL)
            try? FileManager.default.removeItem(at: profileURL)
        }

        let request = SignRequest(
            inputIPA: paths.input,
            outputIPA: paths.output,
            certificate: makeCert(),
            password: p12Password,
            adhoc: false,
            bundleID: "com.bat.e2e",
            displayName: "E2E Signed"
        )
        var logLines: [String] = []
        try SignEngine.sign(request) { logLines.append($0) }

        XCTAssertTrue(FileManager.default.fileExists(atPath: paths.output.path),
                      "Signed output missing. Engine log:\n\(logLines.joined(separator: "\n"))")

        let reader = try ZipReader(url: paths.output)
        XCTAssertNotNil(reader.entry(named: "Payload/BatFixture.app/embedded.mobileprovision"))
        XCTAssertNotNil(reader.entry(named: "Payload/BatFixture.app/_CodeSignature/CodeResources"))

        let infoEntry = try XCTUnwrap(reader.entry(named: "Payload/BatFixture.app/Info.plist"))
        let infoData = try reader.readData(infoEntry)
        let plist = try XCTUnwrap(try PropertyListSerialization.propertyList(from: infoData, options: [], format: nil) as? [String: Any])
        XCTAssertEqual(plist["CFBundleIdentifier"] as? String, "com.bat.e2e")
        XCTAssertEqual(plist["CFBundleDisplayName"] as? String, "E2E Signed")

        let exeEntry = try XCTUnwrap(reader.entry(named: "Payload/BatFixture.app/BatFixture"))
        let exeData = try reader.readData(exeEntry)
        XCTAssertTrue(exeData.contains([0x1d, 0x00, 0x00, 0x00]), "Signed binary lacks LC_CODE_SIGNATURE")
    }

    func testAdhocSigningPipeline() throws {
        let paths = try makeFixtureIPA()
        defer {
            try? FileManager.default.removeItem(at: paths.input)
            try? FileManager.default.removeItem(at: paths.output)
        }
        let request = SignRequest(inputIPA: paths.input, outputIPA: paths.output,
                                  certificate: nil, password: nil, adhoc: true)
        XCTAssertNoThrow(try SignEngine.sign(request) { _ in })
        XCTAssertTrue(FileManager.default.fileExists(atPath: paths.output.path))
    }
}

extension Data {
    func contains(_ pattern: [UInt8]) -> Bool {
        let bytes = [UInt8](self)
        guard pattern.count <= bytes.count else { return false }
        for start in 0...(bytes.count - pattern.count) {
            if Array(bytes[start..<(start + pattern.count)]) == pattern { return true }
        }
        return false
    }
}

private extension SigningE2ETests {
    static let P12_BASE64 = """

"""

    static let PROV_BASE64 = """

"""

    static let MACHO_BASE64 = """

"""
}
